// Main computational kernel
// A: i x j
//
// Optimized version:
//   * Reuses a pre-built traverser over the interior points.
//   * Uses for_dims<'i'> to traverse row-by-row explicitly.
//   * For each row, builds three 1D views (i-1, i, i+1) using fix<'i'>,
//     so vertical neighbours are accessed without recreating full 2D states.
//   * Within a row, only horizontal neighbours are formed via state
//     arithmetic on the 'j' index (two state updates instead of eight).
//   * The update order (i-major, then j) is preserved exactly, so the
//     Gauss–Seidel semantics remain unchanged.
[[gnu::flatten, gnu::noinline]]
void kernel_seidel_2d(int tsteps, auto A) {
	using namespace noarr;

	// grid size in each spatial dimension
	const std::size_t n_i = A | get_length<'i'>();
	const std::size_t n_j = A | get_length<'j'>();

	// Pre-build a traverser over interior points: i,j in [1, n-2].
	// This is reused in each time step and only defines the iteration
	// space; it does not cache values of A.
	auto interior_trav = traverser(A)
		.order(slice<'i'>(1, n_i - 2) ^ slice<'j'>(1, n_j - 2));

	// Constant denominator; using a named constant avoids repeatedly
	// materializing the literal while preserving exact arithmetic.
	const num_t denom = num_t(9.0);

	#pragma scop
	for (int t = 0; t <= tsteps - 1; t++) {
		// Traverse one row of interior points at a time.
		// for_dims<'i'> fixes the current row index 'i' and leaves 'j'
		// as the remaining dimension for the inner traversal.
		interior_trav.template for_dims<'i'>([&](auto trav_i) {
			// trav_i has:
			//   - 'i' fixed to the current row
			//   - 'j' free and ranging over [1, n_j-2]
			auto s_i = trav_i.state();
			const std::size_t i = get_index<'i'>(s_i); // 1 <= i <= n_i-2

			// Build three 1D row views that share A's storage:
			//   row_im1: row i-1
			//   row_i  : row i
			//   row_ip1: row i+1
			//
			// These views have only the 'j' dimension; they ignore any
			// 'i' index present in states passed to operator[].
			auto row_im1 = A ^ fix<'i'>(i - 1);
			auto row_i   = A ^ fix<'i'>(i);
			auto row_ip1 = A ^ fix<'i'>(i + 1);

			// Now sweep all interior columns in this row.
			trav_i.for_each([&](auto state) {
				// state contains both 'i' and 'j', but row_* views only
				// use 'j' and silently ignore 'i'.

				// Horizontal neighbours: compute once and reuse for all
				// three rows. This replaces multiple 2D neighbour()
				// calls with two simple state arithmetic operations.
				auto s_left  = state - idx<'j'>(1); // (i, j-1)
				auto s_mid   = state;               // (i, j)
				auto s_right = state + idx<'j'>(1); // (i, j+1)

				// 3x3 stencil:
				//   [i-1][j-1..j+1]
				//   [ i ][j-1..j+1]
				//   [i+1][j-1..j+1]
				num_t sum =
					  row_im1[s_left ] + row_im1[s_mid ] + row_im1[s_right]
					+ row_i  [s_left ] + row_i  [s_mid ] + row_i  [s_right]
					+ row_ip1[s_left ] + row_ip1[s_mid ] + row_ip1[s_right];

				// In-place Gauss–Seidel update; same arithmetic as the
				// original kernel, but with fewer state manipulations.
				row_i[s_mid] = sum / denom;
			});
		});
	}
	#pragma endscop
}

} // namespace


