// Main computational kernel
// A: i x j
//
// Optimizations (while preserving original semantics):
//  - The spatial traversal of the interior is pre‑constructed once, outside
//    the time loop, so that the relatively expensive composition of
//    proto‑structures (slice + into_blocks) is not repeated every timestep.
//  - 2D tiling is introduced using noarr::into_blocks on both 'i' and 'j'.
//    The tile sizes are tunable (BLOCK_I, BLOCK_J). The way into_blocks is
//    composed guarantees that the *global* update order of points (i, j)
//    remains identical to the original lexicographic order:
//        for i = 1 .. n_i-2
//          for j = 1 .. n_j-2
//    This is essential to preserve Gauss–Seidel semantics.
//  - The division by 9.0 is replaced with a multiplication by a precomputed
//    reciprocal (inv9) to give the compiler a cheaper operation.
[[gnu::flatten, gnu::noinline]]
void kernel_seidel_2d(int tsteps, auto A) {
	using namespace noarr;

	// grid size in each spatial dimension
	const std::size_t n_i = A | get_length<'i'>();
	const std::size_t n_j = A | get_length<'j'>();

	// Length of the interior region (we skip the boundary points)
	const std::size_t interior_i_len = n_i - 2;
	const std::size_t interior_j_len = n_j - 2;

	// Tunable tile sizes (can be adapted to cache sizes / target machine)
	constexpr std::size_t BLOCK_I_DESIRED = 32;
	constexpr std::size_t BLOCK_J_DESIRED = 32;

	// Choose actual tile sizes so that the interior lengths are multiples of
	// the block sizes. This satisfies the assumption of noarr::into_blocks,
	// and avoids having to handle remainder tiles separately.
	//
	// We degrade to smaller factors of the desired size if necessary, and
	// finally to 1 (no tiling) in the worst case.
	auto choose_block = [](std::size_t interior_len,
	                       std::size_t desired) -> std::size_t {
		if (interior_len == 0)
			return 1; // degenerate, but harmless (no iterations anyway)

		std::size_t b = desired;
		if (b > interior_len)
			b = interior_len;

		while (b > 1 && (interior_len % b) != 0)
			--b;

		return b;
	};

	const std::size_t block_i = choose_block(interior_i_len, BLOCK_I_DESIRED);
	const std::size_t block_j = choose_block(interior_j_len, BLOCK_J_DESIRED);

	// Precompute 1/9 as a constant so the kernel can use a multiplication
	// instead of a division in the innermost loop.
	const num_t inv9 = num_t(1.0) / num_t(9.0);

	// Pre-build a traverser over the *interior* of the domain, with 2D
	// tiling in both spatial dimensions.
	//
	// Composition order:
	//   - slice<'i'>(1, interior_i_len) restricts i to [1, n_i-2]
	//   - slice<'j'>(1, interior_j_len) restricts j to [1, n_j-2]
	//   - into_blocks<'i','I','i'>(block_i) decomposes i into (I, i)
	//   - into_blocks<'j','J','j'>(block_j) decomposes j into (J, j)
	//
	// Final traversal has logical nest:
	//   for I blocks of rows
	//     for i rows inside a block
	//       for J blocks of columns
	//         for j columns inside a block
	//
	// Because I is outside i and J is outside j (and we *do not* hoist
	// block indices above the original dimensions), the global order of
	// (i, j) pairs is still:
	//   i = 1..n_i-2 (outer), j = 1..n_j-2 (inner),
	// exactly as in the original kernel.
	//
	// IMPORTANT: We apply these transformations via `order`, so the state
	//            seen in the lambda is still expressed in the original
	//            indices ('i', 'j'), which makes neighbor() valid and
	//            keeps semantics straightforward.
	auto interior_trav =
		traverser(A).order(
			slice<'i'>(1, interior_i_len) ^
			slice<'j'>(1, interior_j_len) ^
			into_blocks<'i', 'I', 'i'>(block_i) ^
			into_blocks<'j', 'J', 'j'>(block_j)
		);

	#pragma scop
	for (int t = 0; t <= tsteps - 1; t++) {
		// Traverse only the interior points: i, j in [1, n-2]
		// The prebuilt traverser already applies the necessary slices and
		// tiling. The state seen here still provides the *original* indices
		// (i, j), suitable for neighbor().
		interior_trav.for_each([&](auto state) {
			auto s = state;

			// Build states for all 8 neighbors and the center.
			// The interior slice guarantee ensures these all remain in range.
			auto s_im1_jm1 = neighbor<'i', 'j'>(s, -1, -1);
			auto s_im1_j   = neighbor<'i'>(s, -1);
			auto s_im1_jp1 = neighbor<'i', 'j'>(s, -1, +1);

			auto s_i_jm1   = neighbor<'j'>(s, -1);
			auto s_i_j     = s;
			auto s_i_jp1   = neighbor<'j'>(s, +1);

			auto s_ip1_jm1 = neighbor<'i', 'j'>(s, +1, -1);
			auto s_ip1_j   = neighbor<'i'>(s, +1);
			auto s_ip1_jp1 = neighbor<'i', 'j'>(s, +1, +1);

			// Sum the 3x3 stencil around (i, j)
			num_t sum =
				A[s_im1_jm1] + A[s_im1_j] + A[s_im1_jp1] +
				A[s_i_jm1]   + A[s_i_j]   + A[s_i_jp1] +
				A[s_ip1_jm1] + A[s_ip1_j] + A[s_ip1_jp1];

			// Gauss–Seidel in-place update
			A[s_i_j] = sum * inv9;
		});
	}
	#pragma endscop
}

