// Main computational kernel
// A: i x j
//
// This version keeps the same Gauss–Seidel update order as the original
// implementation (row-major sweep over interior points) but reduces the
// number of memory loads per stencil evaluation.
//
// Idea:
//   - We traverse the interior in row-major order: for each interior row `i`,
//     we sweep j = 1 .. n_j-2 in increasing order.
//   - For each row we maintain a 3x3 sliding window of values around the
//     current point (i, j):
//         north_* : row i-1  at columns j-1, j, j+1
//         mid_*   : row i    at columns j-1, j, j+1
//         south_* : row i+1  at columns j-1, j, j+1
//   - Rows i-1 and i+1 are *not* modified while we are processing row i,
//     so their values can be safely cached and slid horizontally.
//   - For the middle row i, only the center point (i, j) is updated at
//     the current step. The left neighbor (i, j-1) is always the value
//     computed earlier in this time step; the center (i, j) and right
//     (i, j+1) are the "old" values from the previous step. We cache the
//     old center/right values and reuse them between columns, while the
//     newly computed center value is reused as the left neighbor for the
//     next column.
//
// Loads per row (length ≈ n_j):
//   - First interior column in the row: 9 loads (same as naive).
//   - Each subsequent interior column: 3 new loads
//       (one new "right" value for each of the three rows).
//   - Total per row ≈ 3 * n_j instead of 9 * (n_j - 2),
//     while preserving exact Gauss–Seidel semantics.
//
[[gnu::flatten, gnu::noinline]]
void kernel_seidel_2d(int tsteps, auto A) {
	using namespace noarr;

	// grid size in each spatial dimension
	const std::size_t n_i = A | get_length<'i'>();
	const std::size_t n_j = A | get_length<'j'>();

	// No interior points: nothing to do
	if (n_i < 3 || n_j < 3 || tsteps <= 0)
		return;

	// Precompute 1/9 once
	const num_t inv9 = num_t(1.0) / num_t(9.0);

	// Slices selecting the interior region: i, j in [1, n-2]
	auto interior_i = slice<'i'>(1, n_i - 2);
	auto interior_j = slice<'j'>(1, n_j - 2);

	// Base traverser over interior rows only (i in [1, n_i-2])
	auto rows_trav = traverser(A).order(interior_i);

	// For the horizontal sliding window we need to know up to which j
	// we should prepare data for the *next* point (we don't slide after
	// the last interior column).
	const std::size_t last_interior_j          = n_j - 2;      // j_max (inclusive)
	const std::size_t last_interior_j_minus_one = last_interior_j - 1; // j_max - 1

	#pragma scop
	for (int t = 0; t <= tsteps - 1; ++t) {
		// Traverse interior rows: i in [1, n_i-2]
		rows_trav.template for_dims<'i'>([&](auto row_trav_outer) {
			// row_trav_outer: traverser with 'i' fixed, full j-dimension.
			// Limit to interior columns j in [1, n_j-2].
			auto row_trav = row_trav_outer.order(interior_j);

			// 3x3 sliding window caches around (i, j)
			num_t north_left  = num_t(0);
			num_t north_mid   = num_t(0);
			num_t north_right = num_t(0);

			num_t mid_left_new   = num_t(0); // (i, j-1), already updated in this t-step
			num_t mid_center_old = num_t(0); // (i, j), value from previous t-step
			num_t mid_right_old  = num_t(0); // (i, j+1), value from previous t-step

			num_t south_left  = num_t(0);
			num_t south_mid   = num_t(0);
			num_t south_right = num_t(0);

			bool first_in_row = true;

			// Sweep interior columns in increasing j
			row_trav.template for_dims<'j'>([&](auto cell_trav) {
				// Center state (i, j) for the current stencil
				auto state_center = cell_trav.state();

				if (first_in_row) {
					// Initialization for j == 1: explicitly load the full 3x3
					// neighborhood around (i, 1)
					auto state_north_center = neighbor<'i'>(state_center, -1); // (i-1, j)
					auto state_south_center = neighbor<'i'>(state_center, +1); // (i+1, j)

					auto state_north_left  = neighbor<'j'>(state_north_center, -1);
					auto state_north_right = neighbor<'j'>(state_north_center, +1);

					auto state_south_left  = neighbor<'j'>(state_south_center, -1);
					auto state_south_right = neighbor<'j'>(state_south_center, +1);

					auto state_mid_left  = neighbor<'j'>(state_center, -1);
					auto state_mid_right = neighbor<'j'>(state_center, +1);

					north_left  = A[state_north_left];
					north_mid   = A[state_north_center];
					north_right = A[state_north_right];

					south_left  = A[state_south_left];
					south_mid   = A[state_south_center];
					south_right = A[state_south_right];

					// Middle row: (i, j-1), (i, j), (i, j+1)
					// j-1 is boundary or previously updated; j and j+1 are old.
					mid_left_new   = A[state_mid_left];
					mid_center_old = A[state_center];
					mid_right_old  = A[state_mid_right];

					first_in_row = false;
				}

				// At this point the caches represent:
				//   north_* : (i-1, j-1/j/j+1)
				//   mid_*   : (i,   j-1/j/j+1) with mid_left_new already updated
				//   south_* : (i+1, j-1/j/j+1)

				// Compute the 9-point stencil
				num_t sum =
					north_left + north_mid + north_right +
					mid_left_new + mid_center_old + mid_right_old +
					south_left + south_mid + south_right;

				num_t new_center = sum * inv9;

				// Gauss–Seidel in-place update
				A[state_center] = new_center;

				// Slide window one column to the right if there is another
				// interior column in this row.
				auto j = get_index<'j'>(state_center);
				if (j <= last_interior_j_minus_one) {
					// New right column index is j + 2.
					auto state_north_new_right = neighbor<'i', 'j'>(state_center, -1, +2);
					auto state_mid_new_right   = neighbor<'j'>(state_center, +2);
					auto state_south_new_right = neighbor<'i', 'j'>(state_center, +1, +2);

					// Rows i-1 and i+1: values do not change during processing
					// of row i, so we can reuse cached left/mid and only load
					// the new rightmost column.
					north_left  = north_mid;
					north_mid   = north_right;
					north_right = A[state_north_new_right];

					south_left  = south_mid;
					south_mid   = south_right;
					south_right = A[state_south_new_right];

					// Middle row:
					//   - new left neighbor for column j+1 is the value we just
					//     wrote to (i, j)
					//   - old center for column j+1 is the previous right_old
					//   - old right for column j+1 is loaded at j+2
					mid_left_new   = new_center;
					mid_center_old = mid_right_old;
					mid_right_old  = A[state_mid_new_right];
				}
			});
		});
	}
	#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	int tsteps = TSTEPS;

	// configure layout and lengths
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);

	// initialize data
	init_array(A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_seidel_2d(tsteps, A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (optional, to prevent dead-code elimination / check correctness)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
