using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// A is an N x N matrix indexed by (i, j)
	// layout: i = row index (outer), j = column index (inner / contiguous)
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);
} tuning;


// Array initialization
// A: i x j
void init_array(auto A) {
	using namespace noarr;

	// grid size inferred from the structure
	auto n = A | get_length<'i'>();
	auto n_val = static_cast<num_t>(n);

	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		A[state] = (static_cast<num_t>(i) * (static_cast<num_t>(j) + num_t(2))
		            + num_t(2))
		           / n_val;
	});
}


// Main computational kernel
// A: i x j
//
// Optimization notes:
//
//  - The traverser over the interior points is created once and reused
//    for every time step (instead of being reconstructed in each t-iteration).
//
//  - Neighbor states are built in a structured way:
//        first shift in 'i' (rows): i-1, i, i+1
//        then shift in 'j' (columns): j-1, j, j+1
//    This reduces the amount of state arithmetic compared to computing all
//    8 neighbors with 2D shifts.
//
//  - The constant 1/9 is precomputed as `inv9` and the update uses a
//    multiplication instead of a division. Modern compilers do this anyway,
//    but making it explicit clarifies intent and can help optimization.
//
//  - We keep the traversal order `i` outer / `j` inner, matching the
//    physical layout to maximize spatial locality and allow good cache use.
//
//  - No spatial parallelization is introduced, because the in-place
//    Gauss–Seidel update has true data dependencies along both dimensions
//    (each point depends on already updated neighbors in the same step).
//    A naive parallel for over i or j would break semantics.
[[gnu::flatten, gnu::noinline]]
void kernel_seidel_2d(int tsteps, auto A) {
	using namespace noarr;

	// grid size in each spatial dimension
	const std::size_t n_i = A | get_length<'i'>();
	const std::size_t n_j = A | get_length<'j'>();

	// Degenerate cases: nothing to do and avoid creating invalid slices
	if (tsteps <= 0 || n_i <= 2 || n_j <= 2)
		return;

	// Pre-build traverser over the interior points: i, j in [1, n-2]
	// `slice` is applied via `order`, so states in the lambda still
	// see the original indices (1 .. n-2), which is exactly what
	// neighbor<'i'/'j'>(...) expects.
	auto interior_trav = traverser(A)
		.order(slice<'i'>(1, n_i - 2) ^ slice<'j'>(1, n_j - 2));

	// Precompute constant 1/9 to turn division into a multiply
	const num_t inv9 = num_t(1.0) / num_t(9.0);

	#pragma scop
	for (int t = 0; t < tsteps; ++t) {
		interior_trav.for_each([&](auto state) {
			// Central point state (i, j)
			auto s_i_j = state;

			// First shift in the vertical direction (rows)
			auto s_im1_j = noarr::neighbor<'i'>(s_i_j, -1);
			auto s_ip1_j = noarr::neighbor<'i'>(s_i_j, +1);

			// Now generate the 3 x 3 neighborhood by shifting in 'j'
			// Top row
			auto s_im1_jm1 = noarr::neighbor<'j'>(s_im1_j, -1);
			auto s_im1_jp1 = noarr::neighbor<'j'>(s_im1_j, +1);

			// Middle row
			auto s_i_jm1   = noarr::neighbor<'j'>(s_i_j, -1);
			auto s_i_jp1   = noarr::neighbor<'j'>(s_i_j, +1);

			// Bottom row
			auto s_ip1_jm1 = noarr::neighbor<'j'>(s_ip1_j, -1);
			auto s_ip1_jp1 = noarr::neighbor<'j'>(s_ip1_j, +1);

			// Accumulate the 9-point stencil
			num_t sum =
				A[s_im1_jm1] + A[s_im1_j] + A[s_im1_jp1] +
				A[s_i_jm1]   + A[s_i_j]   + A[s_i_jp1]   +
				A[s_ip1_jm1] + A[s_ip1_j] + A[s_ip1_jp1];

			// In-place Gauss–Seidel update
			A[s_i_j] = sum * inv9;
		});
	}
	#pragma endscop
}

} // namespace


int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	int tsteps = TSTEPS;

	// configure layout and lengths
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(n);

	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);

	// initialize data
	init_array(A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_seidel_2d(tsteps, A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// print results (optional, to prevent dead-code elimination / check correctness)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, A.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
