// ---------------------------------------------------------------------------
// Array initialization
// A: i x j
// ---------------------------------------------------------------------------
void init_array(auto A) {
	using namespace noarr;

	// grid size inferred from the structure (i and j have same length here)
	auto n = A | get_length<'i'>();
	auto n_val = static_cast<num_t>(n);

	// Use multiplication by the reciprocal instead of division inside the loop.
	// This is mathematically equivalent but typically faster.
	const num_t inv_n = num_t(1.0) / n_val;

	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		const num_t fi = static_cast<num_t>(i);
		const num_t fj = static_cast<num_t>(j);

		// Original formula:
		//   A[i][j] = (i * (j + 2) + 2) / n
		// Rewritten to use inv_n:
		A[state] = (fi * (fj + num_t(2.0)) + num_t(2.0)) * inv_n;
	});
}


// ---------------------------------------------------------------------------
// Main computational kernel: 2D 9‑point Gauss–Seidel / Seidel stencil
// A: i x j
//
// Optimized version:
//  - Preserves the original lexicographic sweep (i outer, j inner).
//  - Traversal is still entirely expressed using Noarr traversers.
//  - For each interior row, we use a 3x3 sliding window in j-direction:
//      * For the first interior column in a row, we load all 9 neighbors.
//      * For subsequent columns, we "slide" the window one column right:
//          - reuse 6 previously loaded values,
//          - load only the 3 new right-column neighbors.
//    -> reduces memory loads from ~9 per point to ~3 per point for large rows.
//  - We still read neighbors through Noarr states (via neighbor<...>).
//  - We store updated center values into both A and the sliding window cache
//    so that the in-place Gauss–Seidel semantics are preserved.
// ---------------------------------------------------------------------------
[[gnu::flatten, gnu::noinline]]
void kernel_seidel_2d(int tsteps, auto A) {
	using namespace noarr;

	// grid size in each spatial dimension
	const auto n_i = A | get_length<'i'>();
	const auto n_j = A | get_length<'j'>();

	// constant factor 1/9 to replace division in the inner loop
	const num_t inv9 = num_t(1.0) / num_t(9.0);

	// Build a traverser over all interior rows, i in [1, n_i-2].
	// Columns will be handled per-row.
	auto rows_trav = traverser(A).order(
		slice<'i'>(1, n_i - 2) // restrict i to interior
	);

	#pragma scop
	for (int t = 0; t <= tsteps - 1; t++) {
		// Traverse interior rows: i in [1, n_i-2]
		rows_trav.template for_dims<'i'>([&](auto row_trav_base) {
			// row_trav_base has 'i' fixed and still ranges over 'j'.
			// Now restrict columns to j in [1, n_j-2] for this specific row.
			auto row_trav = row_trav_base.order(
				slice<'j'>(1, n_j - 2)
			);

			// Sliding 3x3 window cache for this row.
			// Layout (r = row, c = column within the window):
			//
			//   [ tl  tc  tr ]   row i-1
			//   [ ml  mc  mr ]   row i
			//   [ bl  bc  br ]   row i+1
			//
			// For the first column in the row, we fill all 9 from memory.
			// For subsequent columns, we shift left:
			//   (tl, tc, tr) <= (tc, tr, new_right_top)
			//   (ml, mc, mr) <= (mc, mr, new_right_mid)
			//   (bl, bc, br) <= (bc, br, new_right_bot)
			// and only load the 3 new right-column neighbors.
			num_t tl = num_t(0), tc = num_t(0), tr = num_t(0);
			num_t ml = num_t(0), mc = num_t(0), mr = num_t(0);
			num_t bl = num_t(0), bc = num_t(0), br = num_t(0);

			bool first_in_row = true;

			row_trav.for_each([&](auto state) {
				// `state` always corresponds to the current center (i, j).
				// No manual loops over i/j: traversal is entirely controlled
				// by Noarr traversers and the slice above.

				if (first_in_row) {
					// First interior column in this row: j == 1
					first_in_row = false;

					auto s = state;

					// North and south centers relative to current (i, j)
					auto s_im1 = neighbor<'i'>(s, -1); // (i-1, j)
					auto s_ip1 = neighbor<'i'>(s, +1); // (i+1, j)

					// Row i-1: (i-1, j-1), (i-1, j), (i-1, j+1)
					tl = A[neighbor<'j'>(s_im1, -1)];
					tc = A[s_im1];
					tr = A[neighbor<'j'>(s_im1, +1)];

					// Row i: (i, j-1), (i, j), (i, j+1)
					ml = A[neighbor<'j'>(s, -1)];
					mc = A[s];
					mr = A[neighbor<'j'>(s, +1)];

					// Row i+1: (i+1, j-1), (i+1, j), (i+1, j+1)
					bl = A[neighbor<'j'>(s_ip1, -1)];
					bc = A[s_ip1];
					br = A[neighbor<'j'>(s_ip1, +1)];

					// Compute the 9-point average
					num_t sum =
						tl + tc + tr +
						ml + mc + mr +
						bl + bc + br;

					num_t new_center = sum * inv9;

					// In-place Gauss–Seidel update: write back to A
					A[s] = new_center;

					// The center becomes the "left middle" neighbor for the
					// next column, so we keep the updated value in the cache.
					mc = new_center;
				} else {
					// Subsequent interior columns in this row: j >= 2
					auto s = state;

					// Slide the window one column to the right.
					// Left column <= center column, center column <= right column.
					tl = tc;
					ml = mc;
					bl = bc;

					tc = tr;
					mc = mr;
					bc = br;

					// Load the new right column at (i-1, j+1), (i, j+1), (i+1, j+1).
					auto s_jp1       = neighbor<'j'>(s, +1);          // (i,   j+1)
					auto s_im1_jp1   = neighbor<'i'>(s_jp1, -1);      // (i-1, j+1)
					auto s_ip1_jp1   = neighbor<'i'>(s_jp1, +1);      // (i+1, j+1)

					tr = A[s_im1_jp1];
					mr = A[s_jp1];
					br = A[s_ip1_jp1];

					// Compute the 9-point average using the updated window.
					num_t sum =
						tl + tc + tr +
						ml + mc + mr +
						bl + bc + br;

					num_t new_center = sum * inv9;

					// In-place Gauss–Seidel update: write back to A
					A[s] = new_center;

					// As before, the just-updated center will be used as
					// mid-left in the next column.
					mc = new_center;
				}
			});
		});
	}
	#pragma endscop
}

